import UnifyAppsUserSession from "./userSession/UnifyAppsUserSession";

class NativeUAAnalytics {
  static instance: NativeUAAnalytics | null = null;

  unifyAppsUserSession: UnifyAppsUserSession;

  private constructor() {
    this.unifyAppsUserSession = new UnifyAppsUserSession();
  }

  static getInstance() {
    if (!NativeUAAnalytics.instance) {
      NativeUAAnalytics.instance = new NativeUAAnalytics();
    }
    return NativeUAAnalytics.instance;
  }

  static setSessionTimeout(timeout: string) {
    NativeUAAnalytics.getInstance().unifyAppsUserSession.setSessionTimeout(parseInt(timeout));
  }

  static startSessionIfNeeded() {
    NativeUAAnalytics.getInstance().unifyAppsUserSession.startSessionIfNeeded();
  }

  static updateLastActiveTimestamp() {
    NativeUAAnalytics.getInstance().unifyAppsUserSession.updateLastActiveTimestamp();
  }

  static getSessionId() {
    return NativeUAAnalytics.getInstance().unifyAppsUserSession.getSessionId();
  }

  static saveUserDetails(userDetails: string) {
    return window.localStorage.setItem("userDetails", userDetails);
  }

  static getUserDetails() {
    return window.localStorage.getItem("userDetails");
  }

  static getConstants(){
    return {}
  }
}

export default NativeUAAnalytics;
